FAMILY_ORDER = ("support_routing", "rule_application", "evidence_entailment", "comparative_nuance")

def serialize(rows):
    return "".join(json.dumps(row, ensure_ascii=False, separators=(",", ":")) + "\n" for row in rows)

def materialize(output: Path, ci: bool = False):
    rows = CASES
    expected = FULL_SHA256
    if ci:
        rows = []
        for family in FAMILY_ORDER:
            rows.extend([row for row in CASES if row["family"] == family][:2])
        expected = CI_SHA256
    payload = serialize(rows)
    digest = hashlib.sha256(payload.encode()).hexdigest()
    if digest != expected:
        raise RuntimeError(f"scorer-gate fixture hash mismatch: expected {expected}, got {digest}")
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(payload, encoding="utf-8")
    return digest

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--ci", action="store_true")
    args = parser.parse_args()
    digest = materialize(args.output, ci=args.ci)
    print(json.dumps({"output": str(args.output), "sha256": digest}, sort_keys=True))
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
